import XCTest
@testable import KhojMesh

/// Checks this package against docs/interop/khoj_test_vectors.json (generated by the Kotlin code).
final class VectorTests: XCTestCase {
    private var v: [String: Any] = [:]

    override func setUpWithError() throws {
        let bundle = Bundle.module
        let url = try XCTUnwrap(bundle.url(forResource: "khoj_test_vectors", withExtension: "json")
            ?? bundle.url(forResource: "khoj_test_vectors", withExtension: "json", subdirectory: "Resources"))
        v = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    }

    private func hex(_ s: String) -> [UInt8] {
        var out: [UInt8] = [], i = s.startIndex
        while i < s.endIndex {
            let j = s.index(i, offsetBy: 2)
            out.append(UInt8(s[i..<j], radix: 16)!)
            i = j
        }
        return out
    }
    private func str(_ d: [String: Any], _ k: String) -> String { d[k] as! String }
    private func beacon() -> [String: Any] { v["beacon"] as! [String: Any] }
    private func crew() throws -> CrewKey { try XCTUnwrap(CrewKey(code: str(v, "crew_code"))) }

    func testKeyDerivation() throws {
        let c = try crew()
        XCTAssertEqual(c.packetKey.withUnsafeBytes { [UInt8]($0) }, hex(str(v, "content_key_hex")))
        XCTAssertEqual(c.tagKey.withUnsafeBytes { [UInt8]($0) }, hex(str(v, "tag_key_hex")))
        XCTAssertEqual(c.tunnelKey.withUnsafeBytes { [UInt8]($0) }, hex(str(v, "tunnel_key_hex")))
        XCTAssertEqual(Int(c.crewId), v["crew_id_int32_be"] as? Int)
        XCTAssertEqual(c.tagForTime(1790000000), (v["crew_tag_uint64"] as? NSNumber)?.uint64Value)
        XCTAssertNotNil(CrewKey(code: "abcd-efgh-jklm-npqr"), "case and dashes are accepted")
        XCTAssertNil(CrewKey(code: "ABCDEFGHJKLMNPQ0"), "0 is not in the alphabet")
        XCTAssertNil(CrewKey(code: "ABCDEFGHJKLMNPQ"), "too short")
    }

    func testDecryptBeaconFrame() throws {
        let c = try crew()
        let b = beacon()
        let p = try XCTUnwrap(MeshPacket.decode(hex(str(b, "frame_hex"))))
        let f = b["fields"] as! [String: Any]
        XCTAssertEqual(Int(p.type.rawValue), (f["type"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.ttl), (f["ttl"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.hops), (f["hops"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.linkSeq), (f["linkSeq"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.relayId), (f["relayId"] as! NSNumber).intValue)
        XCTAssertEqual(p.crewTag, (f["crewTag"] as! NSNumber).uint64Value)
        XCTAssertEqual(Int(p.runEpoch), (f["runEpoch"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.originId), (f["originId"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.packetId), (f["packetId"] as! NSNumber).intValue)
        XCTAssertEqual(Int(p.originTimeS), (f["originTimeS"] as! NSNumber).intValue)
        XCTAssertTrue(c.matchesTag(p.crewTag, unixSeconds: UInt64(p.originTimeS)))
        XCTAssertEqual(p.aad(), hex(str(b, "aad_hex")))

        let plain = try XCTUnwrap(c.open(p))
        XCTAssertEqual(plain, hex(str(b, "plaintext_hex")))
        XCTAssertEqual(MeshMessage.decode(type: p.type, body: plain),
                       .beacon(lat: 25.3176, lon: 82.9739, accuracyM: 12, battery: 80, name: "Asha", findable: false))

        // A relay changes only link fields, so the relayed copy still opens; tampering with the body or end-to-end fields does not.
        XCTAssertEqual(c.open(p.relayed(by: 42, linkSeq: 9, lowPower: true)), plain)
        var bad = p; bad.body[0] ^= 1
        XCTAssertNil(c.open(bad))
        bad = p; bad.originTimeS += 1
        XCTAssertNil(c.open(bad))
    }

    func testEncodeBeaconFrameByteForByte() throws {
        let c = try crew()
        let b = beacon()
        let f = b["fields"] as! [String: Any]
        let message = MeshMessage.beacon(lat: 25.3176, lon: 82.9739, accuracyM: 12, battery: 80, name: "Asha", findable: false)
        XCTAssertEqual(message.encode(), hex(str(b, "plaintext_hex")))

        var p = MeshPacket(type: message.type,
                           ttl: UInt8((f["ttl"] as! NSNumber).uint8Value),
                           hops: UInt8((f["hops"] as! NSNumber).uint8Value),
                           linkSeq: UInt16((f["linkSeq"] as! NSNumber).uint16Value),
                           relayId: Int32((f["relayId"] as! NSNumber).int32Value),
                           crewTag: (f["crewTag"] as! NSNumber).uint64Value,
                           runEpoch: Int32((f["runEpoch"] as! NSNumber).int32Value),
                           originId: Int32((f["originId"] as! NSNumber).int32Value),
                           packetId: Int32((f["packetId"] as! NSNumber).int32Value),
                           originTimeS: UInt32((f["originTimeS"] as! NSNumber).uint32Value),
                           body: [])
        var nonce: [UInt8] = []
        nonce.appendBE(p.runEpoch); nonce.appendBE(p.originId); nonce.appendBE(p.packetId)
        XCTAssertEqual(nonce, hex(str(b, "nonce_hex")))
        p.body = try c.seal(p, plaintext: message.encode())
        XCTAssertEqual(p.body.count, message.encode().count + (b["gcm_tag_bytes"] as! Int))
        XCTAssertEqual(p.encoded(), hex(str(b, "frame_hex")))
    }

    func testPublicSosFrame() throws {
        let frame = hex(str(v, "public_sos_frame_hex"))
        let p = try XCTUnwrap(MeshPacket.decode(frame))
        XCTAssertEqual(p.type, .publicSos)
        XCTAssertTrue(p.type.isPublic)
        XCTAssertEqual(p.crewTag, 0)
        XCTAssertEqual(MeshMessage.decode(type: p.type, body: p.body), .publicSos(kind: 0, lat: 25.3176, lon: 82.9739, label: "Asha"))
        XCTAssertEqual(p.encoded(), frame)
        XCTAssertEqual(MeshMessage.publicSos(kind: 0, lat: 25.3176, lon: 82.9739, label: "Asha").encode(), p.body)
    }

    func testMessageRoundTrips() {
        let messages: [MeshMessage] = [
            .sos(lat: -33.8688, lon: 151.2093, note: "help"), .rally(lat: 1.5, lon: -2.5, meetAtS: 1_790_000_000, label: "gate 4"),
            .text("hi"), .ack(originId: -5, packetId: 7),
        ]
        for m in messages { XCTAssertEqual(MeshMessage.decode(type: m.type, body: m.encode()), m) }
        XCTAssertNil(MeshMessage.decode(type: .sos, body: [1, 2, 3]), "too short")
        var out = MeshMessage.sos(lat: 0, lon: 0, note: "").encode(); out[0] = 0x7F // lat far above 90 degrees
        XCTAssertNil(MeshMessage.decode(type: .sos, body: out))
    }

    func testMalformedFramesAreRejected() throws {
        let frame = hex(str(beacon(), "frame_hex"))
        XCTAssertNil(MeshPacket.decode(Array(frame.dropLast())), "length byte no longer matches")
        var bad = frame; bad[0] = 0x4C
        XCTAssertNil(MeshPacket.decode(bad), "bad magic")
        bad = frame; bad[4] = 9
        XCTAssertNil(MeshPacket.decode(bad), "ttl above 8")
        XCTAssertNil(MeshPacket.decode(Array(frame.prefix(10))))
    }

    func testGattFragments() throws {
        let frame = hex(str(beacon(), "frame_hex"))
        for (key, id, mtu) in [("gatt_fragments_mtu185_hex", UInt8(1), 185), ("gatt_fragments_mtu23_hex", UInt8(2), 23)] {
            let expected = (v[key] as! [String]).map { hex($0) }
            XCTAssertEqual(GattFraming.split(frameId: id, frame: frame, mtu: mtu), expected, key)
            var joiner = GattFraming.Joiner()
            let results = expected.map { joiner.add($0) }
            XCTAssertEqual(results.last!, frame, key)
            XCTAssertTrue(results.dropLast().allSatisfy { $0 == nil }, "no frame before the last fragment")
        }
        // Out-of-order fragments are dropped, not joined wrongly.
        var joiner = GattFraming.Joiner()
        let frags = GattFraming.split(frameId: 3, frame: frame, mtu: 23)!
        XCTAssertNil(joiner.add(frags[1])); XCTAssertNil(joiner.add(frags[2])); XCTAssertNil(joiner.add(frags[3]))
        XCTAssertNil(GattFraming.split(frameId: 0, frame: [UInt8](repeating: 0, count: 200), mtu: 3), "needs more than 15 fragments")
    }
}
